/**
 * Стили KaTeX импортом ради побочного эффекта (`katexEngine.ts`): у пакета
 * `katex` нет типов для `.css`, а сборка кита идёт голым `tsc` без `vite/client`,
 * в строгом режиме импорт падал бы с TS2882. Пустое объявление — этого достаточно:
 * значения импорт не даёт. В `dist` оно не нужно, наружу типы не выходят.
 */
declare module "katex/dist/katex.min.css";
